package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;
import org.json.*;
/** List browsing uses the previews returned with the authorized list response. */
final class ListsView extends LinearLayout {
 interface Actions {void open(JSONObject list);void create();void filter(String query,int scope);}
 static String fold(String value){return java.text.Normalizer.normalize(value,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(new java.util.Locale("pt","BR")).trim();}
 static boolean matches(JSONObject list,String query,int scope){if(scope==1&&!list.optBoolean("mine")||scope==2&&list.optBoolean("mine"))return false;String source=fold(list.optString("nome")+" "+(list.optBoolean("mine")?"Sua lista":list.optString("owner_name","Amigo")));for(String word:fold(query).split("\\s+"))if(!source.contains(word))return false;return true;}
 static String visibility(JSONObject list){return list.optBoolean("compartilhada")?"Compartilhada com amigos":"Privada";}
 private final JSONArray lists;private final Actions actions;private final EditText search;private final Spinner scope;private final TextView count;private final LinearLayout cards;
 ListsView(Context c,JSONArray lists,String query,int selected,Actions actions){super(c);this.lists=lists;this.actions=actions;setTag("lists-view");setOrientation(VERTICAL);setFocusableInTouchMode(true);addView(NativeSheet.text(c,"Suas listas",26,0xffedf2f8));Button create=new Button(c);create.setText("＋ Nova lista");create.setTag("lists-create");AppStyle.button(create,true);addView(create,new LayoutParams(-1,-2));create.setOnClickListener(v->actions.create());
  search=NativeSheet.input(c,"Buscar por nome ou pessoa",120);search.setTag("lists-search");search.setContentDescription("Buscar listas por nome ou pessoa");search.setSingleLine(true);search.setText(query);addView(search);scope=NativeSheet.options(c,new String[]{"Todas as listas","Minhas listas","Dos amigos"});scope.setTag("lists-scope");scope.setContentDescription("Exibir listas");scope.setSelection(selected);addView(scope);count=NativeSheet.text(c,"",12,0xffbfc8d5);count.setTag("lists-count");count.setAccessibilityLiveRegion(ACCESSIBILITY_LIVE_REGION_POLITE);addView(count);cards=new LinearLayout(c);cards.setOrientation(VERTICAL);addView(cards);
  search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int n,int x){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int a,int b,int n){draw();}});scope.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int position,long id){draw();}});draw();requestFocus();
 }
 private void draw(){cards.removeAllViews();String query=search.getText().toString();int selected=scope.getSelectedItemPosition(),visible=0;for(int i=0;i<lists.length();i++){JSONObject list=lists.optJSONObject(i);if(list==null||!matches(list,query,selected))continue;visible++;cards.addView(card(list));}count.setText(visible+ (visible==1?" lista":" listas")+(visible!=lists.length()?" de "+lists.length():""));if(visible==0){LinearLayout empty=new LinearLayout(getContext());empty.setOrientation(VERTICAL);empty.setPadding(dp(18),dp(20),dp(18),dp(20));empty.setBackground(AppStyle.shape(empty,NativeTheme.panel(getContext()),18));empty.addView(NativeSheet.text(getContext(),lists.length()==0?"Nenhuma lista criada":"Nenhuma lista encontrada",20,0xffedf2f8));Button action=new Button(getContext());action.setTag("lists-empty-action");action.setText(lists.length()==0?"Nova lista":"Limpar busca e filtros");AppStyle.button(action,false);empty.addView(action,new LayoutParams(-1,-2));action.setOnClickListener(v->{if(lists.length()==0)actions.create();else{scope.setSelection(0);search.setText("");draw();}});cards.addView(empty);}actions.filter(query,selected);}
 private View card(JSONObject list){Context c=getContext();LinearLayout card=new LinearLayout(c){public CharSequence getAccessibilityClassName(){return Button.class.getName();}};card.setOrientation(VERTICAL);card.setTag("list-card-"+list.optString("id"));card.setBackground(AppStyle.interactive(card,NativeTheme.panel(c),18));card.setClipToOutline(true);LayoutParams outer=new LayoutParams(-1,-2);outer.setMargins(0,0,0,dp(16));card.setLayoutParams(outer);card.setFocusable(true);card.setDescendantFocusability(FOCUS_BLOCK_DESCENDANTS);int total=Math.max(0,list.optInt("count"));String owner=list.optBoolean("mine")?"Sua lista":"Lista de "+list.optString("owner_name","amigo");card.setContentDescription(list.optString("nome")+". "+visibility(list)+". "+owner+". "+total+" títulos. Abrir lista");
  ArtworkFrame art=new ArtworkFrame(c,16f/9f);art.setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);LinearLayout mosaic=new LinearLayout(c);mosaic.setOrientation(VERTICAL);art.addView(mosaic,new FrameLayout.LayoutParams(-1,-1));JSONArray preview=list.optJSONArray("preview");for(int row=0;row<2;row++){LinearLayout line=new LinearLayout(c);mosaic.addView(line,new LayoutParams(-1,0,1));for(int col=0;col<2;col++){JSONObject title=preview==null?null:preview.optJSONObject(row*2+col);FrameLayout tile=new FrameLayout(c);tile.setBackgroundColor((row+col)%2==0?NativeTheme.soft(c):NativeTheme.panel(c));LayoutParams lp=new LayoutParams(0,-1,1);lp.setMargins(col==0?0:dp(2),row==0?0:dp(2),0,0);line.addView(tile,lp);TextView fallback=NativeSheet.text(c,"◇",25,NativeTheme.accent(c));fallback.setGravity(Gravity.CENTER);tile.addView(fallback,new FrameLayout.LayoutParams(-1,-1));if(title!=null&&!title.optString("capa").isEmpty()){ImageView image=new ImageView(c);image.setScaleType(ImageView.ScaleType.CENTER_CROP);tile.addView(image,new FrameLayout.LayoutParams(-1,-1));SensitiveCover.load(image,title,()->AccountImageLoader.load(image,title.optString("capa")));}}}card.addView(art,new LayoutParams(-1,-2));
  LinearLayout body=new LinearLayout(c);body.setOrientation(VERTICAL);body.setPadding(dp(16),dp(14),dp(16),dp(14));TextView badge=NativeSheet.text(c,visibility(list),11,list.optBoolean("compartilhada")?NativeTheme.accent(c):0xffbfc8d5);body.addView(badge);TextView name=NativeSheet.text(c,list.optString("nome","Lista"),20,0xffedf2f8);name.setTypeface(null,Typeface.BOLD);body.addView(name);body.addView(NativeSheet.text(c,owner,12,0xffbfc8d5));body.addView(NativeSheet.text(c,total+(total==1?" título":" títulos")+"  ·  Abrir lista →",12,NativeTheme.accent(c)));card.addView(body);body.setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);card.setOnClickListener(v->actions.open(list));return card;
 }
 private int dp(int n){return NativeSheet.dp(getContext(),n);}
}
